<script setup lang="ts">
import { computed } from 'vue';
import type { components } from '../api/contracts.generated';
import { api } from '../api/http';
import { status, time, value } from '../api/display';
import { useResource } from '../state/resource';
const props = defineProps<{ id: string }>();
const { data, error, busy, load } = useResource(signal => api<components['schemas']['JobEventPageResponse']>(`/api/v1/jobs/${encodeURIComponent(props.id)}/events?after=${encodeURIComponent(props.id + ':0')}`, 'GET', undefined, signal));
const result = computed(() => data.value?.snapshot.publication ?? data.value?.snapshot.validation);
const state = computed(() => data.value?.snapshot.validation?.validationState ?? data.value?.snapshot.publication?.state);
</script>
<template><section class="surface" :aria-busy="busy"><div class="section-heading"><h2>{{ data?.snapshot.kind === 'publish' ? '发布任务' : '校验任务' }}</h2><div class="actions"><a href="#history">返回历史</a><button :disabled="busy" @click="load">刷新任务</button></div></div><p v-if="error" class="notice danger" role="alert">{{ error }}</p><p v-else-if="busy" class="muted">正在获取任务…</p><template v-else-if="data && result"><p class="status-label" :class="state">{{ status(state) }}</p><dl class="facts"><dt>任务标识</dt><dd class="mono">{{ id }}</dd><dt>版本 / 序号</dt><dd>{{ result.version ?? '待校验' }} / {{ value(result.sequence) }}</dd><dt>清单摘要</dt><dd class="mono">{{ result.manifestSha256 ?? '—' }}</dd><dt>更新包摘要</dt><dd class="mono">{{ result.packageSha256 ?? '—' }}</dd><dt>创建时间</dt><dd>{{ time(result.createdUtcMs) }}</dd><dt>错误代码</dt><dd class="mono">{{ result.errorCode ?? '—' }}</dd></dl><template v-if="data.snapshot.validation"><h3>签名中的更新说明</h3><pre class="log-lines">{{ data.snapshot.validation.releaseNotes?.join('\n') || '暂无说明' }}</pre><p class="muted">有效期至 {{ time(data.snapshot.validation.manifestExpiresUtcMs) }}</p></template><template v-if="data.snapshot.publication"><p class="muted">下载检查：{{ data.snapshot.publication.downloadCheck?.lastSucceeded == null ? '尚无结果' : data.snapshot.publication.downloadCheck.lastSucceeded ? '通过' : '未通过' }} · {{ time(data.snapshot.publication.downloadCheck?.lastCompletedUtcMs) }}</p><p v-if="state === 'completed'" class="notice">正式清单已生效。客户端下载和安装由用户决定。</p><p v-if="state === 'activeUnverified'" class="notice danger">清单已经生效，下载检查未通过；请核对分发服务后重试检查。</p></template><h3>任务阶段</h3><p v-if="data.reset" class="muted">部分早期事件可能已清理，以当前任务快照为准。</p><ol class="event-list"><li v-for="event in data.events" :key="event.id"><time>{{ time(event.createdUtcMs) }}</time>{{ event.stage }} · {{ event.code }}</li></ol></template></section></template>
